                cds = cur.execute(q).fetchall()
                if not cds:
                    continue
            run_cds: list[int] = []
            for cd in sorted([x[0] for x in cds]):
                delta = cd - (time.time() - self.vol_act[rp])
                if delta > 0:
                    ret = min(ret, delta)
                    break
                run_cds.append(cd)
