    def init_indexes(
        self, all_vols: dict[str, VFS], scan_vols: list[str], fscan: bool
    ) -> bool:
        gid = self.gid
        while self.pp and gid == self.gid:
            time.sleep(0.1)
        if gid != self.gid:
            return False
        if gid:
            self.log("reload
        self.pp = ProgressPrinter()
        vols = list(all_vols.values())
