    def _determine_detail_view_tabs(self):
        """Determine the layout for the detail view tabs that are intrinsic to this serializer."""
        tabs = self.get_additional_detail_view_tabs()
        if hasattr(self.Meta, "detail_view_config"):
            detail_view_config = self._validate_view_config(self.Meta.detail_view_config)
        else:
            detail_view_config = self._get_default_detail_view_config()
        detail_view_config = self._refine_detail_view_config(detail_view_config, tabs)
        return {
            bettertitle(self.Meta.model._meta.verbose_name): detail_view_config,
            **tabs,
        }
    def _get_default_detail_view_config(self):
        """
        Generate detail view config for the view based on the serializer's fields.
        Examples:
            >>> DeviceSerializer._get_default_detail_view_config().
            {
                "layout":[
                    {
                        Device: {
                            "fields": ["name", "subdevice_role", "height", "comments"...]
                        }
                    },
                    {
                        Tags: {
                            "fields": ["tags"]
                        }
                    }
                ]
            }
        Returns:
            (list): A list representing the view config.
        """
        m2m_fields, other_fields = self._get_m2m_and_non_m2m_fields()
        model_verbose_name = self.Meta.model._meta.verbose_name
        return {
            "layout": [
                {
                    bettertitle(model_verbose_name): {
                        "fields": [field["name"] for field in other_fields],
                    }
                },
                {field["label"]: {"fields": [field["name"]]} for field in m2m_fields},
            ]
        }
def get_route_for_model(model, action, api=False):
    """
    Return the URL route name for the given model and action. Does not perform any validation.
    Supports both core and plugin routes.
    Args:
        model (models.Model, str): Class, Instance, or dotted string of a Django Model
        action (str): name of the action in the route
        api (bool): If set, return an API route.
    Returns:
        (str): return the name of the view for the model/action provided.
    Examples:
        >>> get_route_for_model(Device, "list")
        "dcim:device_list"
        >>> get_route_for_model(Device, "list", api=True)
        "dcim-api:device-list"
        >>> get_route_for_model("dcim.location", "list")
        "dcim:location_list"
        >>> get_route_for_model("dcim.location", "list", api=True)
        "dcim-api:location-list"
        >>> get_route_for_model(ExampleModel, "list")
        "plugins:example_plugin:examplemodel_list"
        >>> get_route_for_model(ExampleModel, "list", api=True)
        "plugins-api:example_plugin-api:examplemodel-list"
    """
    if isinstance(model, str):
        model = get_model_from_name(model)
    suffix = "" if not api else "-api"
    if model is ContentType:
        app_label = "extras"
    elif model is Group:
        app_label = "users"
    else:
        app_label = model._meta.app_label
    prefix = f"{app_label}{suffix}:{model._meta.model_name}"
    sep = ""
    if action != "":
        sep = "_" if not api else "-"
    viewname = f"{prefix}{sep}{action}"
    if model._meta.app_label in settings.PLUGINS:
        viewname = f"plugins{suffix}:{viewname}"
    return viewname
