def is_target_path_valid(path: pathlib.Path, target: pathlib.Path) -> bool:
    try:
        if path.is_absolute():
            target.resolve().relative_to(path)
        else:
            target.resolve().relative_to(pathlib.Path(os.getcwd()).joinpath(path))
    except ValueError:
        return False
    return True
def get_memory_limit():
    """
    Get memory limit for allocating decompression chunk buffer.
    :return: allowed chunk size in bytes.
    """
    default_limit = int(128e6)
    if sys.platform.startswith("win"):
        return default_limit
    else:
        import resource
        soft, _ = resource.getrlimit(resource.RLIMIT_AS)
        if soft == -1:
            avmem = psutil.virtual_memory().available
            return min(default_limit, (avmem - int(256e6)) >> 2)
        else:
            return min(default_limit, (soft - int(256e6)) >> 2)
