class Timer(object):
    def __init__(self, duration):
        self.duration = duration
        self.start()
    def start(self):
        self.target = time() + self.duration
    def reset(self):
        self.start()
    def get(self):
        return self.duration - (self.target - time())
    def set(self, duration):
        self.duration = duration
    def finished(self):
        return time() > self.target
